{
  "items": [
    {
      "title": "Eurostat – Individuals: Internet Use (2002–2025)",
      "url_or_doi": "https://doi.org/10.2908/isoc_ci_ifp_iu",
      "justification": "Official Eurostat dataset measuring internet usage among individuals in Germany. Includes annual observations for 2020–2025, with breakdowns by age, gender, education, employment status, and other demographic characteristics. Particularly useful for studying internet adoption, digital inclusion, and inequalities in Germany's information society during the 2020s."
    },
    {
      "title": "Eurostat – Individuals: Internet Activities (2002–2025)",
      "url_or_doi": "https://doi.org/10.2908/isoc_ci_ac_i",
      "justification": "Provides detailed statistics on how people use the internet in Germany, including social networking, online communication, internet banking, information searches, and digital services. Contains observations from the 2020s and demographic breakdowns. Suitable for examining changes in digital behavior, online participation, and the development of Germany's information society."
    },
    {
      "title": "Eurostat – Households: Internet Access",
      "url_or_doi": "https://ec.europa.eu/eurostat/web/products-datasets/-/isoc_ci_in_h",
      "justification": "Official European statistical dataset covering household internet access, including Germany. Provides annual data spanning 2020–2025 and earlier years. Useful for analyzing internet connectivity, household digital infrastructure, and differences in access to information and communication technologies."
    },
    {
      "title": "Eurostat – Households: Type of Connection to the Internet (2003–2021)",
      "url_or_doi": "https://doi.org/10.2908/isoc_ci_it_h",
      "justification": "Historical Eurostat dataset describing household internet connection technologies, including broadband connectivity. Contains German observations for 2020 and 2021, making it useful for analyzing the beginning of the 2020s and establishing a baseline for subsequent changes in digital infrastructure."
    },
    {
      "title": "Eurostat – Survey on ICT Usage in Households and by Individuals: Research Microdata (2008–2025)",
      "url_or_doi": "https://ec.europa.eu/eurostat/web/microdata/collections-research/survey-ict-use-households-individuals",
      "justification": "Provides access to anonymized individual-level survey data covering information and communication technology usage across European countries, including Germany subject to dataset availability and access authorization. The 2020–2025 releases support detailed research into internet access, digital skills, e-commerce, online public services, privacy, and demographic inequalities. Particularly valuable for statistical modeling and academic research. Access to scientific-use microdata requires approval."
    },
    {
      "title": "Destatis – ICT Usage in Private Households (IKT-Nutzung in privaten Haushalten)",
      "url_or_doi": "https://www.destatis.de/DE/Themen/Gesellschaft-Umwelt/Einkommen-Konsum-Lebensbedingungen/IT-Nutzung/_inhalt.html",
      "justification": "Official German Federal Statistical Office statistical collection covering information and communication technology usage among German households and individuals. Includes downloadable statistical reports for 2023, 2024, and 2025, alongside links to historical statistics. Covers internet access, online activities, digital communication, e-commerce, and demographic differences. One of the most directly relevant German sources for researching the information society during the 2020s."
    },
    {
      "title": "Destatis GENESIS-Online – ICT Usage in Private Households, Statistics 12231",
      "url_or_doi": "https://genesis.destatis.de/datenbank/online/statistics",
      "justification": "Official German statistical database containing the ICT household survey under statistical series 12231. Provides structured data on computer ownership, internet usage, online shopping, internet activities, and digital competencies. Supports comparisons across years and demographic groups. Particularly useful for obtaining downloadable statistical tables and constructing longitudinal datasets for Germany."
    },
    {
      "title": "Destatis GENESIS-Online – Computer and Internet Skills by Age Group (2021–2025)",
      "url_or_doi": "https://genesis.destatis.de/datenbank/online/statistic/122%2A/table/12231-0003",
      "justification": "Specific official German statistical table containing data from 2021–2025 on computer and internet competencies among people aged 16–74. Includes age-group breakdowns and indicators of digital skills. Highly relevant for investigating digital literacy, generational inequalities, and digital inclusion within Germany's information society."
    },
    {
      "title": "Destatis – Private Internet Activities in Germany: Time Series (2021–2025)",
      "url_or_doi": "https://www.destatis.de/DE/Themen/Gesellschaft-Umwelt/Einkommen-Konsum-Lebensbedingungen/IT-Nutzung/Tabellen/nutzung-internet-privatezwecke-zvgl-mz-ikt.html",
      "justification": "Official German time-series dataset reporting percentages of individuals engaging in different online activities between 2021 and 2025. Includes social media participation, online banking, email communication, video calls, online product searches, and online selling. Especially useful for analyzing behavioral changes in German society following the COVID-19 pandemic and the growing importance of digital services."
    },
    {
      "title": "Destatis GENESIS-Online – ICT Indicators for German Enterprises (2025)",
      "url_or_doi": "https://genesis.destatis.de/datenbank/online/statistic/52911/table/52911-0005/search/s/NTI5MTE%3D",
      "justification": "Official German statistical table measuring the adoption of information and communication technologies by businesses in 2025. Includes business internet connectivity, website adoption, connection speeds, online services, and other ICT indicators. Useful for studying enterprise digitalization and the economic dimension of Germany's information society."
    },
    {
      "title": "Destatis GENESIS-Online – ICT Indicators for Enterprises by Economic Sector (2025)",
      "url_or_doi": "https://genesis.destatis.de/datenbank/online/url/c4270cd6",
      "justification": "Official statistical dataset providing sector-specific information about ICT adoption among German enterprises in 2025. Includes indicators concerning artificial intelligence, IT security, data protection, and barriers to technology adoption. Particularly relevant for analyzing digital transformation across industries and emerging challenges associated with information technologies."
    },
    {
      "title": "Eurostat – ICT Usage in Enterprises: German Statistics",
      "url_or_doi": "https://ec.europa.eu/eurostat/cache/metadata/en/isoc_e_simsie_de.htm",
      "justification": "Official Eurostat metadata and dataset access information for the German enterprise ICT survey. The underlying annual statistics cover digital technologies, e-commerce, business connectivity, and the adoption of advanced ICT solutions. Relevant for analyzing business digitalization during the 2020s and comparing German enterprises with those in other European countries. This URL leads to the German survey metadata rather than an individual downloadable data table."
    },
    {
      "title": "Eurostat – Digital Economy and Society: Comprehensive Database",
      "url_or_doi": "https://ec.europa.eu/eurostat/web/digital-economy-and-society/database/comprehensive-database",
      "justification": "Comprehensive official European database bringing together statistical indicators on the digital economy and information society. Includes Germany and covers internet access, ICT adoption, digital skills, e-commerce, e-government, and enterprise digitalization. Particularly useful for identifying multiple datasets covering 2020–2025 and conducting comparative research between Germany and other EU countries."
    },
    {
      "title": "German Federal Network Agency – Broadband Atlas (Breitbandatlas), 2022–2025",
      "url_or_doi": "https://bundesnetzagentur.de/GIGA/DE/Breitbandatlas/start.html",
      "justification": "Official German broadband infrastructure dataset documenting the geographical availability of fixed and mobile internet connectivity. Provides information covering June 2022 through December 2025, including broadband technologies and network availability. Particularly useful for studying regional digital divides, broadband infrastructure development, and geographical inequalities in access to the information society."
    },
    {
      "title": "German Federal Network Agency – Gigabit Register (Gigabit-Grundbuch)",
      "url_or_doi": "https://gigabitgrundbuch.bund.de",
      "justification": "Official German government information platform providing access to information about broadband and telecommunications infrastructure. Established in 2022, it integrates resources such as the Broadband Atlas and infrastructure planning information. Relevant for researching Germany's digital infrastructure expansion, connectivity disparities, and the geographical foundations of the information society during the 2020s. Some infrastructure datasets require restricted access."
    },
    {
      "title": "Destatis GENESIS-Online – Household Digital Equipment and Internet Access (2006–2020)",
      "url_or_doi": "https://genesis.destatis.de/datenbank/online/statistic/12231/table/12231-9000",
      "justification": "Official German statistical dataset documenting household ownership of computers, communication devices, and internet connections through 2020. Includes national and regional comparisons. Although its time series ends in 2020, it provides a useful baseline for examining the subsequent development of Germany's information society during the 2020s."
    }
  ]
}
